import type { QueryGroup, QueryNode, QueryOperator } from "./query-builder";

const queryOperators = new Set<QueryOperator>([
    "equals", "not-equals", "contains", "greater-than", "less-than",
    "is-empty", "is-not-empty",
]);

const minimumColumnWidth = 48;
const maximumColumnWidth = 1200;

type WorkViewSort = {
    columnId: string;
    direction: "ascending" | "descending";
};

type WorkViewPinnedColumns = {
    left: readonly string[];
    right: readonly string[];
};

/** A persisted, versioned list-view configuration. */
type WorkViewConfig = {
    version: 1;
    layout?: "table" | "list" | "board" | "calendar" | "timeline";
    filter: QueryGroup;
    sorts: readonly WorkViewSort[];
    groupBy: string | null;
    visibleColumns: readonly string[];
    columnOrder: readonly string[];
    columnWidths: Readonly<Record<string, number>>;
    pinnedColumns: WorkViewPinnedColumns;
};

type SavedWorkView = {
    id: string;
    name: string;
    scope: "private" | "shared";
    config: WorkViewConfig;
};

type WorkViewColumnOption = {
    id: string;
    label: string;
    sortable?: boolean;
    groupable?: boolean;
};

function createWorkViewConfig(
    columnIds: readonly string[], filterId = "root",
): WorkViewConfig {
    const uniqueIds = [...columnIds];
    if (uniqueIds.length === 0 || uniqueIds.some((id) =>
        typeof id !== "string" || !id.trim()) ||
        new Set(uniqueIds).size !== uniqueIds.length) {
        throw new Error("createWorkViewConfig needs unique, nonempty columns.");
    }
    if (typeof filterId !== "string" || !filterId.trim()) {
        throw new Error("createWorkViewConfig needs a nonempty filter ID.");
    }
    return {
        version: 1,
        filter: {
            kind: "group",
            id: filterId,
            combinator: "all",
            children: [],
        },
        sorts: [],
        groupBy: null,
        visibleColumns: [...uniqueIds],
        columnOrder: [...uniqueIds],
        columnWidths: Object.fromEntries(
            uniqueIds.map((id) => [id, 180]),
        ),
        pinnedColumns: { left: [], right: [] },
    };
}

function cloneQueryNode(node: QueryNode): QueryNode {
    if (node.kind === "condition") return { ...node };
    return { ...node, children: node.children.map(cloneQueryNode) };
}

function cloneWorkViewConfig(config: WorkViewConfig): WorkViewConfig {
    return {
        ...config,
        filter: cloneQueryNode(config.filter) as QueryGroup,
        sorts: config.sorts.map((sort) => ({ ...sort })),
        visibleColumns: [...config.visibleColumns],
        columnOrder: [...config.columnOrder],
        columnWidths: { ...config.columnWidths },
        pinnedColumns: {
            left: [...config.pinnedColumns.left],
            right: [...config.pinnedColumns.right],
        },
    };
}

function assertWorkViewConfig(
    config: WorkViewConfig,
    columnIds: readonly string[],
): void {
    if (!config || config.version !== 1) {
        throw new RangeError("WorkViewConfig supports version 1 only.");
    }
    if (config.layout !== undefined && ![
        "table", "list", "board", "calendar", "timeline",
    ].includes(config.layout)) {
        throw new RangeError("WorkViewConfig layout is not supported.");
    }
    if (!config.filter || config.filter.kind !== "group" ||
        !config.pinnedColumns ||
        !Array.isArray(config.pinnedColumns.left) ||
        !Array.isArray(config.pinnedColumns.right) ||
        !config.columnWidths || typeof config.columnWidths !== "object") {
        throw new Error("WorkViewConfig has an invalid structure.");
    }

    const available = new Set(columnIds);
    if (available.size !== columnIds.length ||
        [...available].some((id) => !id.trim())) {
        throw new Error("WorkView columns need unique, nonempty IDs.");
    }

    function assertColumnList(ids: readonly string[], name: string) {
        if (!Array.isArray(ids) || ids.some((id) =>
            typeof id !== "string" || !available.has(id)) ||
            new Set(ids).size !== ids.length) {
            throw new Error(`WorkViewConfig has invalid ${name}.`);
        }
    }

    assertColumnList(config.columnOrder, "column order");
    assertColumnList(config.visibleColumns, "visible columns");
    assertColumnList(config.pinnedColumns.left, "left pinned columns");
    assertColumnList(config.pinnedColumns.right, "right pinned columns");
    if (config.visibleColumns.length === 0) {
        throw new Error("WorkViewConfig must show at least one column.");
    }
    if (config.columnOrder.length !== available.size ||
        [...available].some((id) => !config.columnOrder.includes(id))) {
        throw new Error("WorkViewConfig column order must include every column.");
    }
    const pinned = new Set(config.pinnedColumns.left);
    if (config.pinnedColumns.right.some((id) => pinned.has(id))) {
        throw new Error("A WorkView column cannot be pinned on both sides.");
    }

    if (config.groupBy !== null && !available.has(config.groupBy)) {
        throw new Error("WorkViewConfig has an unknown group column.");
    }
    if (!Array.isArray(config.sorts) || config.sorts.some((sort) =>
        !sort || !available.has(sort.columnId) ||
        (sort.direction !== "ascending" &&
            sort.direction !== "descending")) ||
        new Set(config.sorts.map((sort) => sort.columnId)).size !==
            config.sorts.length) {
        throw new Error("WorkViewConfig has invalid sort rules.");
    }

    const widthEntries = Object.entries(config.columnWidths);
    if (widthEntries.some(([id, width]) => !available.has(id) ||
        !Number.isInteger(width) || width < minimumColumnWidth ||
        width > maximumColumnWidth)) {
        throw new Error("WorkViewConfig has invalid column widths.");
    }

    const nodeIds = new Set<string>();
    const nodes: { node: QueryNode; depth: number }[] = [
        { node: config.filter, depth: 1 },
    ];
    while (nodes.length) {
        const { node, depth } = nodes.pop()!;
        if (!node || typeof node.id !== "string" || !node.id.trim() ||
            nodeIds.has(node.id)) {
            throw new Error("WorkViewConfig filter IDs must be unique.");
        }
        nodeIds.add(node.id);
        if (node.kind === "group") {
            if (depth > 4 || !Array.isArray(node.children) ||
                (node.combinator !== "all" && node.combinator !== "any")) {
                throw new Error("WorkViewConfig has an invalid filter group.");
            }
            nodes.push(...node.children.map((child) => ({
                node: child,
                depth: depth + 1,
            })));
        } else if (node.kind === "condition") {
            if (typeof node.fieldId !== "string" ||
                typeof node.value !== "string" ||
                !queryOperators.has(node.operator)) {
                throw new Error("WorkViewConfig has an invalid filter condition.");
            }
        } else {
            throw new Error("WorkViewConfig has an unsupported filter node.");
        }
    }
}

function stableQueryNode(node: QueryNode): unknown {
    if (node.kind === "condition") {
        return {
            kind: node.kind,
            id: node.id,
            fieldId: node.fieldId,
            operator: node.operator,
            value: node.value,
        };
    }
    return {
        kind: node.kind,
        id: node.id,
        combinator: node.combinator,
        children: node.children.map(stableQueryNode),
    };
}

function areWorkViewConfigsEqual(
    first: WorkViewConfig,
    second: WorkViewConfig,
): boolean {
    const stable = (config: WorkViewConfig) => JSON.stringify({
        version: config.version,
        layout: config.layout ?? "table",
        filter: stableQueryNode(config.filter),
        sorts: config.sorts.map((sort) => ({
            columnId: sort.columnId,
            direction: sort.direction,
        })),
        groupBy: config.groupBy,
        visibleColumns: config.visibleColumns,
        columnOrder: config.columnOrder,
        columnWidths: Object.fromEntries(
            Object.entries(config.columnWidths).sort(([a], [b]) =>
                a.localeCompare(b),
            ),
        ),
        pinnedColumns: {
            left: config.pinnedColumns.left,
            right: config.pinnedColumns.right,
        },
    });
    return stable(first) === stable(second);
}

export {
    assertWorkViewConfig,
    areWorkViewConfigsEqual,
    cloneWorkViewConfig,
    createWorkViewConfig,
};
export type {
    SavedWorkView,
    WorkViewColumnOption,
    WorkViewConfig,
    WorkViewPinnedColumns,
    WorkViewSort,
};
